#define R iResolution.xy
#define T iTime
#define rot(n) mat2(cos(n),-sin(n),sin(n),cos(n))

float box(vec3 p){
    vec3 q = abs(p);
    return max(q.x,max(q.y,q.z));
}

float scene(vec2 p){
    vec3 ro = vec3(p,1),
         rd = normalize(-ro),
         po = ro;

    float acc;
    float t,h;
    for(int i=0; i<99; i++){
        vec3 q = po;
        q -= vec3(0,0,-1.);
        q.xy *= rot(T);
        q.yz *= rot(T*.9);
        q.xz *= rot(T*1.1);
        h = box(q)-.35;
        t += max(.02,h);
        po = ro+rd*t;
        acc += exp(-h*64.);
        if (t>1e3){
            return acc;
        }
    }
    return acc;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ){
    vec2 uv = 2.*(fragCoord-R*.5)/R.y;

    float val = sin(uv.y*64.+T*8.);

    val = step(val+.9,min(1.,scene(uv)));

    fragColor = vec4(vec3(val),1.0);
}
